/** Source-faithful privileged debug API; access is checked for every component and userdata call. */
public final class DebugCard extends AbstractManagedEnvironment implements DebugNetwork.DebugNode {
    private final EnvironmentHost host;private Optional<AccessContext> access=Optional.empty();private Node remote;private BlockPos remotePosition;
    public DebugCard(EnvironmentHost host){this.host=host;setNode(li.cil.oc.api.Network.newNode(this,Visibility.Neighbors).withComponent("debug").withConnector().create());}
    @Override public ComponentConnector node(){return (ComponentConnector)super.node();}
    private void check(){DebugAccess.check(access);}
    private ServerLevel level(){return (ServerLevel)host.world();}
    private MinecraftServer server(){return level().getServer();}
    private static MinecraftServer server(Context context){return net.neoforged.neoforge.server.ServerLifecycleHooks.getCurrentServer();}
    private static BlockPos pos(Arguments args,int index){return new BlockPos(args.checkInteger(index),args.checkInteger(index+1),args.checkInteger(index+2));}
    private static Direction side(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5)throw new IllegalArgumentException("invalid side");return Direction.from3DDataValue(value);}
    private static ItemStack stack(ServerLevel level,String id,int count,int damage,String snbt){if(count<=0)return ItemStack.EMPTY;ResourceLocation key=ResourceLocation.parse(id);if(!BuiltInRegistries.ITEM.containsKey(key))throw new IllegalArgumentException("invalid item id");ItemStack stack=new ItemStack(BuiltInRegistries.ITEM.get(key),Math.max(0,count));if(stack.isDamageableItem())stack.setDamageValue(Math.max(0,damage));if(!snbt.isBlank())try{CompoundTag data=TagParser.parseTag(snbt);if(data.contains("components")){data.putString("id",id);data.putInt("count",Math.max(1,count));stack=ItemStack.parse(level.registryAccess(),data).orElseThrow(()->new IllegalArgumentException("invalid item components"));}else stack.set(DataComponents.CUSTOM_DATA,CustomData.of(data));}catch(com.mojang.brigadier.exceptions.CommandSyntaxException error){throw new IllegalArgumentException("invalid item NBT: "+error.getMessage());}return stack;}
    private static BlockState state(Arguments args,int index){Block block;if(args.isInteger(index)){int id=args.checkInteger(index);block=BuiltInRegistries.BLOCK.byId(id);if(block==null)throw new IllegalArgumentException("invalid block id");}else{ResourceLocation key=ResourceLocation.parse(args.checkString(index));if(!BuiltInRegistries.BLOCK.containsKey(key))throw new IllegalArgumentException("invalid block id");block=BuiltInRegistries.BLOCK.get(key);}int metadata=args.checkInteger(index+1);List<BlockState> states=block.getStateDefinition().getPossibleStates();if(metadata<0||metadata>=states.size())throw new IllegalArgumentException("invalid block state index");if(metadata==0)return block.defaultBlockState();int defaultIndex=states.indexOf(block.defaultBlockState());return states.get(metadata<=defaultIndex?metadata-1:metadata);}
    @Callback(doc="function(value:number):number -- Changes the component network's energy buffer by the specified delta.") public Object[] changeBuffer(Context context,Arguments args){check();return new Object[]{node().changeBuffer(args.checkDouble(0))};}
    @Callback(doc="function():number -- Get the container's X position in the world.") public Object[] getX(Context context,Arguments args){check();return new Object[]{host.xPosition()};}
    @Callback(doc="function():number -- Get the container's Y position in the world.") public Object[] getY(Context context,Arguments args){check();return new Object[]{host.yPosition()};}
    @Callback(doc="function():number -- Get the container's Z position in the world.") public Object[] getZ(Context context,Arguments args){check();return new Object[]{host.zPosition()};}
    @Callback(doc="function([id:number]):userdata -- Get the world object for the specified dimension ID, or the container's.") public Object[] getWorld(Context context,Arguments args){check();ServerLevel world=args.count()==0?level():args.isInteger(0)?DebugWorlds.level(server(),args.checkInteger(0)):DebugWorlds.level(server(),args.checkString(0));return new Object[]{new WorldValue(world,access)};}
    @Callback(doc="function():table -- Get a list of all world IDs, loaded and unloaded.") public Object[] getWorlds(Context context,Arguments args){check();return new Object[]{DebugWorlds.ids(server())};}
    @Callback(doc="function(name:string):userdata -- Get the entity of a player.") public Object[] getPlayer(Context context,Arguments args){check();return new Object[]{new PlayerValue(args.checkString(0),access)};}
    @Callback(doc="function():table -- Get a list of currently logged-in players.") public Object[] getPlayers(Context context,Arguments args){check();return new Object[]{server().getPlayerList().getPlayerNamesArray()};}
    @Callback(doc="function():userdata -- Get the scoreboard object for the world") public Object[] getScoreboard(Context context,Arguments args){check();return new Object[]{new ScoreboardValue(level(),access)};}
    @Callback(doc="function(x:number, y:number, z:number[, worldId:number]):boolean, string, table -- Returns contents at the location in the specified world, defaulting to the host world.")
    public Object[] scanContentsAt(Context context,Arguments args){
        check();ServerLevel level=args.count()>3?(args.isInteger(3)?DebugWorlds.level(server(),args.checkInteger(3)):DebugWorlds.level(server(),args.checkString(3))):level();BlockPos pos=pos(args,0);
        var player=FakePlayerFactory.get(level,new GameProfile(UUID.fromString(Settings.get().fakePlayerUuid),Settings.get().fakePlayerName));player.setPos(pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5);
        Entity entity=level.getEntities(player,new AABB(pos)).stream().min(Comparator.comparingDouble(player::distanceToSqr)).orElse(null);
        if(entity instanceof LivingEntity)return new Object[]{true,"EntityLivingBase",entity};
        if(entity instanceof AbstractMinecart)return new Object[]{true,"EntityMinecart",entity};
        BlockState state=level.getBlockState(pos);if(state.isAir())return new Object[]{false,"air",state.getBlock()};
        if(!state.getFluidState().isEmpty()||state.canBeReplaced()){var event=new BlockEvent.BreakEvent(level,pos,state,player);NeoForge.EVENT_BUS.post(event);return new Object[]{event.isCanceled(),state.getFluidState().isEmpty()?"replaceable":"liquid",state.getBlock()};}
        return new Object[]{true,state.getCollisionShape(level,pos).isEmpty()?"passable":"solid",state.getBlock()};
    }
    @Callback(doc="function(name:string):boolean -- Get whether a mod or API is loaded.") public Object[] isModLoaded(Context context,Arguments args){check();String id=args.checkString(0);return new Object[]{net.neoforged.fml.ModList.get().isLoaded(id)||net.neoforged.fml.ModList.get().getMods().stream().anyMatch(mod->mod.getModId().equals(id))};}
    @Callback(doc="function(command:string):number -- Runs an arbitrary command using a fake player.") public Object[] runCommand(Context context,Arguments args){check();List<?> commands=args.isTable(0)?new ArrayList<>(args.checkTable(0).values()):List.of(args.checkString(0));ServerPlayer player=access.map(value->server().getPlayerList().getPlayerByName(value.player())).orElse(null);if(player==null)player=FakePlayerFactory.get(level(),new GameProfile(UUID.fromString(Settings.get().fakePlayerUuid),Settings.get().fakePlayerName));StringJoiner messages=new StringJoiner("\n");CommandSource output=new CommandSource(){public void sendSystemMessage(Component message){messages.add(message.getString());}public boolean acceptsSuccess(){return true;}public boolean acceptsFailure(){return true;}public boolean shouldInformAdmins(){return false;}};int[] result={0};int permission=server().isSingleplayer()?4:server().getProfilePermissions(player.getGameProfile());var source=new CommandSourceStack(output,player.position(),player.getRotationVector(),level(),permission,player.getGameProfile().getName(),player.getDisplayName(),server(),player).withCallback((success,value)->result[0]=value);for(Object command:commands)server().getCommands().performPrefixedCommand(source,command instanceof byte[] bytes?new String(bytes,java.nio.charset.StandardCharsets.UTF_8):String.valueOf(command));return new Object[]{result[0],messages.length()==0?null:messages.toString()};}
    private Node find(BlockPos pos){if(!level().hasChunkAt(pos))return null;var block=level().getBlockEntity(pos);if(block instanceof SidedEnvironment sided){for(Direction side:Direction.values()){Node node=sided.sidedNode(side);if(node!=null)return node;}}return block instanceof Environment environment?environment.node():null;}
    @Callback(doc="function(x:number, y:number, z:number):boolean -- Add a component block at the specified coordinates to the computer network.") public Object[] connectToBlock(Context context,Arguments args){check();BlockPos pos=pos(args,0);Node other=find(pos);if(other==null)return new Object[]{null,"no node found at this position"};if(remote!=null)node().disconnect(remote);remote=other;remotePosition=pos;node().connect(other);return new Object[]{true};}
    @Callback(doc="function(player:string, text:string) -- Sends text to the specified player's clipboard if possible.") public Object[] sendToClipboard(Context context,Arguments args){check();ServerPlayer player=server().getPlayerList().getPlayerByName(args.checkString(0));if(player==null)return new Object[]{false,"no such player"};li.cil.oc.common.network.DebugNetworking.clipboard(player,args.checkString(1));return new Object[]{true};}
    @Callback(doc="function(address:string, data...) -- Sends data to the debug card with the specified address.") public Object[] sendToDebugCard(Context context,Arguments args){check();String destination=args.checkString(0);Object[] data=new Object[Math.max(0,args.count()-1)];for(int i=0;i<data.length;i++)data[i]=args.checkAny(i+1);DebugNetwork.getEndpoint(destination).filter(endpoint->endpoint!=this).ifPresent(endpoint->endpoint.receivePacket(li.cil.oc.api.Network.newPacket(address(),destination,0,data)));return new Object[0];}
    @Callback(doc="function():userdata -- Test method for user-data and general value conversion.") public Object[] test(Context context,Arguments args){check();Map<Object,Object> a=new LinkedHashMap<>(),b=new LinkedHashMap<>();a.put("a",true);a.put("b","test");b.put(10,"zxc");b.put(false,a);a.put("c",b);return new Object[]{b,new TestValue(),host.world()};}
    @Override public String address(){return node().address();}
    @Override public void receivePacket(Packet packet){Object[] signal=new Object[packet.data().length+4];signal[0]="debug_message";signal[1]=packet.source();signal[2]=packet.port();signal[3]=0d;System.arraycopy(packet.data(),0,signal,4,packet.data().length);node().sendToReachable("computer.signal",signal);}
    @Override public void onConnect(Node node){if(node==node()){DebugNetwork.add(this);if(remotePosition!=null){remote=find(remotePosition);if(remote!=null)node().connect(remote);else remotePosition=null;}}}
    @Override public void onDisconnect(Node node){if(node==node()){DebugNetwork.remove(this);if(remote!=null)node().disconnect(remote);}else if(node==remote){remote=null;remotePosition=null;}}
    @Override public void load(CompoundTag tag){super.load(tag);access=AccessContext.load(tag);remotePosition=tag.contains("oc:remoteX")?new BlockPos(tag.getInt("oc:remoteX"),tag.getInt("oc:remoteY"),tag.getInt("oc:remoteZ")):null;}
    @Override public void save(CompoundTag tag){super.save(tag);AccessContext.remove(tag);access.ifPresent(value->value.save(tag));if(remotePosition!=null){tag.putInt("oc:remoteX",remotePosition.getX());tag.putInt("oc:remoteY",remotePosition.getY());tag.putInt("oc:remoteZ",remotePosition.getZ());}else{tag.remove("oc:remoteX");tag.remove("oc:remoteY");tag.remove("oc:remoteZ");}}

    public abstract static class AccessibleValue extends AbstractValue {
        protected Optional<AccessContext> access=Optional.empty();
        protected AccessibleValue(){}protected AccessibleValue(Optional<AccessContext> access){this.access=access;}
        protected void check(){DebugAccess.check(access);}
        @Override public void load(CompoundTag tag){access=AccessContext.load(tag);}
        @Override public void save(CompoundTag tag){AccessContext.remove(tag);access.ifPresent(value->value.save(tag));}
    }
    public static final class PlayerValue extends AccessibleValue {
        private String name="";public PlayerValue(){}private PlayerValue(String name,Optional<AccessContext> access){super(access);this.name=name;}
        private Object[] player(Context context,Function<ServerPlayer,Object[]> action){check();ServerPlayer player=server(context).getPlayerList().getPlayerByName(name);return player==null?new Object[]{null,"player is offline"}:action.apply(player);}
        @Callback(doc="function():userdata -- Get the player's world object.") public Object[] getWorld(Context context,Arguments args){return player(context,player->new Object[]{new WorldValue(player.serverLevel(),access)});}
        @Callback(doc="function():string -- Get the player's game type.") public Object[] getGameType(Context context,Arguments args){return player(context,player->new Object[]{player.gameMode.getGameModeForPlayer().getName()});}
        @Callback(doc="function(gametype:string) -- Set the player's game type (survival, creative, adventure).") public Object[] setGameType(Context context,Arguments args){return player(context,player->{player.setGameMode(GameType.byName(args.checkString(0),GameType.SURVIVAL));return new Object[0];});}
        @Callback(doc="function():number, number, number -- Get the player's position.") public Object[] getPosition(Context context,Arguments args){return player(context,player->new Object[]{player.getX(),player.getY(),player.getZ()});}
        @Callback(doc="function(x:number, y:number, z:number) -- Set the player's position.") public Object[] setPosition(Context context,Arguments args){return player(context,player->{player.teleportTo(args.checkDouble(0),args.checkDouble(1),args.checkDouble(2));return new Object[0];});}
        @Callback(doc="function():number -- Get the player's health.") public Object[] getHealth(Context context,Arguments args){return player(context,player->new Object[]{player.getHealth()});}
        @Callback(doc="function():number -- Get the player's max health.") public Object[] getMaxHealth(Context context,Arguments args){return player(context,player->new Object[]{player.getMaxHealth()});}
        @Callback(doc="function(health:number) -- Set the player's health.") public Object[] setHealth(Context context,Arguments args){return player(context,player->{player.setHealth((float)args.checkDouble(0));return new Object[0];});}
        @Callback(doc="function():number -- Get the player's level") public Object[] getLevel(Context context,Arguments args){return player(context,player->new Object[]{player.experienceLevel});}
        @Callback(doc="function():number -- Get the player's total experience") public Object[] getExperienceTotal(Context context,Arguments args){return player(context,player->new Object[]{player.totalExperience});}
        @Callback(doc="function(level:number) -- Add a level to the player's experience level") public Object[] addExperienceLevel(Context context,Arguments args){return player(context,player->{player.giveExperienceLevels(args.checkInteger(0));return new Object[0];});}
        @Callback(doc="function(level:number) -- Remove a level from the player's experience level") public Object[] removeExperienceLevel(Context context,Arguments args){return player(context,player->{player.giveExperienceLevels(-args.checkInteger(0));return new Object[0];});}
        @Callback(doc="function() -- Clear the players inventory") public Object[] clearInventory(Context context,Arguments args){return player(context,player->{player.getInventory().clearContent();player.containerMenu.broadcastChanges();return new Object[0];});}
        @Callback(doc="function(id:string, amount:number, meta:number[, nbt:string]):number -- Adds the item stack to the players inventory") public Object[] insertItem(Context context,Arguments args){return player(context,player->{ItemStack item=stack(player.serverLevel(),args.checkString(0),args.checkInteger(1),args.checkInteger(2),args.optString(3,""));InventoryUtils.addToPlayerInventory(item,player,true);return new Object[0];});}
        @Override public void load(CompoundTag tag){super.load(tag);name=tag.getString("name");}
        @Override public void save(CompoundTag tag){super.save(tag);tag.putString("name",name);}
    }
    public static final class ScoreboardValue extends AccessibleValue {
        private String dimension;private int dimensionId;public ScoreboardValue(){}private ScoreboardValue(ServerLevel level,Optional<AccessContext> access){super(access);dimension=level.dimension().location().toString();dimensionId=DebugWorlds.id(level);}
        private Scoreboard board(Context context){check();return (dimension==null?DebugWorlds.level(server(context),dimensionId):DebugWorlds.level(server(context),dimension)).getScoreboard();}
        private PlayerTeam team(Scoreboard board,String name){PlayerTeam team=board.getPlayerTeam(name);if(team==null)throw new IllegalArgumentException("no such team");return team;}
        private Objective objective(Scoreboard board,String name){Objective objective=board.getObjective(name);if(objective==null)throw new IllegalArgumentException("no such objective");return objective;}
        @Callback(doc="function(team:string) - Add a team to the scoreboard") public Object[] addTeam(Context context,Arguments args){board(context).addPlayerTeam(args.checkString(0));return new Object[0];}
        @Callback(doc="function(teamName: string) - Remove a team from the scoreboard") public Object[] removeTeam(Context context,Arguments args){Scoreboard board=board(context);board.removePlayerTeam(team(board,args.checkString(0)));return new Object[0];}
        @Callback(doc="function(player:string, team:string):boolean - Add a player to a team") public Object[] addPlayerToTeam(Context context,Arguments args){Scoreboard board=board(context);return new Object[]{board.addPlayerToTeam(args.checkString(0),team(board,args.checkString(1)))};}
        @Callback(doc="function(player:string):boolean - Remove a player from their team") public Object[] removePlayerFromTeams(Context context,Arguments args){return new Object[]{board(context).removePlayerFromTeam(args.checkString(0))};}
        @Callback(doc="function(player:string, team:string):boolean - Remove a player from a specific team") public Object[] removePlayerFromTeam(Context context,Arguments args){Scoreboard board=board(context);board.removePlayerFromTeam(args.checkString(0),team(board,args.checkString(1)));return new Object[0];}
        @Callback(doc="function(objectiveName:string, objectiveCriteria:string) - Create a new objective for the scoreboard") public Object[] addObjective(Context context,Arguments args){Scoreboard board=board(context);String name=args.checkString(0);ObjectiveCriteria criteria=ObjectiveCriteria.byName(args.checkString(1)).orElseThrow(()->new IllegalArgumentException("invalid objective criteria"));board.addObjective(name,criteria,Component.literal(name),criteria.getDefaultRenderType(),false,null);return new Object[0];}
        @Callback(doc="function(objectiveName:string) - Remove an objective from the scoreboard") public Object[] removeObjective(Context context,Arguments args){Scoreboard board=board(context);board.removeObjective(objective(board,args.checkString(0)));return new Object[0];}
        private ScoreAccess score(Context context,Arguments args){Scoreboard board=board(context);return board.getOrCreatePlayerScore(ScoreHolder.forNameOnly(args.checkString(0)),objective(board,args.checkString(1)));}
        @Callback(doc="function(playerName:string, objectiveName:string, score:int) - Sets the score of a player for a certain objective") public Object[] setPlayerScore(Context context,Arguments args){score(context,args).set(args.checkInteger(2));return new Object[0];}
        @Callback(doc="function(playerName:string, objectiveName:string):int - Gets the score of a player for a certain objective") public Object[] getPlayerScore(Context context,Arguments args){return new Object[]{score(context,args).get()};}
        @Callback(doc="function(playerName:string, objectiveName:string, score:int) - Increases the score of a player for a certain objective") public Object[] increasePlayerScore(Context context,Arguments args){score(context,args).add(args.checkInteger(2));return new Object[0];}
        @Callback(doc="function(playerName:string, objectiveName:string, score:int) - Decrease the score of a player for a certain objective") public Object[] decreasePlayerScore(Context context,Arguments args){score(context,args).add(-args.checkInteger(2));return new Object[0];}
        @Override public void load(CompoundTag tag){super.load(tag);dimension=tag.contains("dimensionKey")?tag.getString("dimensionKey"):null;dimensionId=tag.getInt("dimension");}
        @Override public void save(CompoundTag tag){super.save(tag);if(dimension!=null)tag.putString("dimensionKey",dimension);tag.putInt("dimension",dimensionId);}
    }
    public static final class WorldValue extends AccessibleValue {
        private String dimension;private int dimensionId;public WorldValue(){}private WorldValue(ServerLevel level,Optional<AccessContext> access){super(access);dimension=level.dimension().location().toString();dimensionId=DebugWorlds.id(level);}
        private ServerLevel world(Context context){check();return dimension==null?DebugWorlds.level(server(context),dimensionId):DebugWorlds.level(server(context),dimension);}
        @Callback(doc="function():number -- Gets the numeric id of the current dimension.") public Object[] getDimensionId(Context context,Arguments args){return new Object[]{DebugWorlds.id(world(context))};}
        @Callback(doc="function():string -- Gets the name of the current dimension.") public Object[] getDimensionName(Context context,Arguments args){return new Object[]{world(context).dimension().location().getPath()};}
        @Callback(doc="function():number -- Gets the seed of the world.") public Object[] getSeed(Context context,Arguments args){return new Object[]{world(context).getSeed()};}
        @Callback(doc="function():boolean -- Returns whether it is currently raining.") public Object[] isRaining(Context context,Arguments args){return new Object[]{world(context).isRaining()};}
        @Callback(doc="function(value:boolean) -- Sets whether it is currently raining.") public Object[] setRaining(Context context,Arguments args){((ServerLevelData)world(context).getLevelData()).setRaining(args.checkBoolean(0));return new Object[0];}
        @Callback(doc="function():boolean -- Returns whether it is currently thundering.") public Object[] isThundering(Context context,Arguments args){return new Object[]{world(context).isThundering()};}
        @Callback(doc="function(value:boolean) -- Sets whether it is currently thundering.") public Object[] setThundering(Context context,Arguments args){((ServerLevelData)world(context).getLevelData()).setThundering(args.checkBoolean(0));return new Object[0];}
        @Callback(doc="function():number -- Get the current world time.") public Object[] getTime(Context context,Arguments args){return new Object[]{world(context).getDayTime()};}
        @Callback(doc="function(value:number) -- Set the current world time.") public Object[] setTime(Context context,Arguments args){world(context).setDayTime((long)args.checkDouble(0));return new Object[0];}
        @Callback(doc="function():number, number, number -- Get the current spawn point coordinates.") public Object[] getSpawnPoint(Context context,Arguments args){BlockPos pos=world(context).getSharedSpawnPos();return new Object[]{pos.getX(),pos.getY(),pos.getZ()};}
        @Callback(doc="function(x:number, y:number, z:number) -- Set the spawn point coordinates.") public Object[] setSpawnPoint(Context context,Arguments args){world(context).setDefaultSpawnPos(pos(args,0),0);return new Object[0];}
        @Callback(doc="function(x:number, y:number, z:number, sound:string, range:number) -- Play a sound at the specified coordinates.") public Object[] playSoundAt(Context context,Arguments args){ServerLevel world=world(context);ResourceLocation sound=ResourceLocation.parse(args.checkString(3));if(!BuiltInRegistries.SOUND_EVENT.containsKey(sound))throw new IllegalArgumentException("invalid sound id");double range=Math.max(0,args.checkInteger(4));BlockPos pos=pos(args,0);var packet=new net.minecraft.network.protocol.game.ClientboundSoundPacket(BuiltInRegistries.SOUND_EVENT.wrapAsHolder(BuiltInRegistries.SOUND_EVENT.get(sound)),net.minecraft.sounds.SoundSource.MASTER,pos.getX(),pos.getY(),pos.getZ(),1,1,world.random.nextLong());for(ServerPlayer player:world.players())if(player.distanceToSqr(pos.getX(),pos.getY(),pos.getZ())<=range*range)player.connection.send(packet);return new Object[0];}
        @Callback(doc="function(x:number, y:number, z:number):number -- Get the ID of the block at the specified coordinates.") public Object[] getBlockId(Context context,Arguments args){return new Object[]{BuiltInRegistries.BLOCK.getId(world(context).getBlockState(pos(args,0)).getBlock())};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Get the metadata of the block at the specified coordinates. Modern block state indices use 0 for the default state.") public Object[] getMetadata(Context context,Arguments args){BlockState state=world(context).getBlockState(pos(args,0));List<BlockState> states=state.getBlock().getStateDefinition().getPossibleStates();int index=states.indexOf(state),defaultIndex=states.indexOf(state.getBlock().defaultBlockState());return new Object[]{index==defaultIndex?0:index<defaultIndex?index+1:index};}
        @Callback(doc="function(x:number, y:number, z:number[, actualState:boolean=false]) - Gets the block state at the specified position. Modern states already contain connection properties.") public Object[] getBlockState(Context context,Arguments args){ServerLevel world=world(context);BlockPos position=pos(args,0);args.optBoolean(3,false);return new Object[]{world.getBlockState(position)};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Check whether the block at the specified coordinates is loaded.") public Object[] isLoaded(Context context,Arguments args){ServerLevel world=world(context);BlockPos position=pos(args,0);return new Object[]{!world.isOutsideBuildHeight(position)&&world.hasChunkAt(position)};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Check whether the block at the specified coordinates has a tile entity.") public Object[] hasTileEntity(Context context,Arguments args){return new Object[]{world(context).getBlockState(pos(args,0)).hasBlockEntity()};}
        @Callback(doc="function(x:number, y:number, z:number):table -- Get the NBT of the block at the specified coordinates.") public Object[] getTileNBT(Context context,Arguments args){var world=world(context);var entity=world.getBlockEntity(pos(args,0));return entity==null?new Object[0]:new Object[]{DebugNbt.table(entity.saveWithFullMetadata(world.registryAccess()))};}
        @Callback(doc="function(x:number, y:number, z:number, nbt:table):boolean -- Set the NBT of the block at the specified coordinates.") public Object[] setTileNBT(Context context,Arguments args){var world=world(context);BlockPos pos=pos(args,0);var entity=world.getBlockEntity(pos);if(entity==null)return new Object[]{null,"no tile entity"};Tag tag=DebugNbt.tag(args.checkTable(3));if(!(tag instanceof CompoundTag compound))return new Object[]{null,"nbt tag compound expected"};entity.loadWithComponents(compound,world.registryAccess());entity.setChanged();world.sendBlockUpdated(pos,entity.getBlockState(),entity.getBlockState(),3);return new Object[]{true};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Get the light opacity of the block at the specified coordinates.") public Object[] getLightOpacity(Context context,Arguments args){var world=world(context);BlockPos pos=pos(args,0);return new Object[]{world.getBlockState(pos).getLightBlock(world,pos)};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Get the light value (emission) of the block at the specified coordinates.") public Object[] getLightValue(Context context,Arguments args){return new Object[]{world(context).getMaxLocalRawBrightness(pos(args,0),0)};}
        @Callback(doc="function(x:number, y:number, z:number):number -- Get whether the block at the specified coordinates is directly under the sky.") public Object[] canSeeSky(Context context,Arguments args){return new Object[]{world(context).canSeeSky(pos(args,0))};}
        @Callback(doc="function(x:number, y:number, z:number, id:number or string, meta:number):number -- Set the block at the specified coordinates. Modern block state indices use 0 for the default state.") public Object[] setBlock(Context context,Arguments args){return new Object[]{world(context).setBlockAndUpdate(pos(args,0),state(args,3))};}
        @Callback(doc="function(x1:number, y1:number, z1:number, x2:number, y2:number, z2:number, id:number or string, meta:number):number -- Set all blocks in the area defined by the two corner points (x1, y1, z1) and (x2, y2, z2). Modern block state indices use 0 for the default state.") public Object[] setBlocks(Context context,Arguments args){ServerLevel world=world(context);BlockPos start=pos(args,0),end=pos(args,3);BlockState state=state(args,6);for(BlockPos pos:BlockPos.betweenClosed(Math.min(start.getX(),end.getX()),Math.min(start.getY(),end.getY()),Math.min(start.getZ(),end.getZ()),Math.max(start.getX(),end.getX()),Math.max(start.getY(),end.getY()),Math.max(start.getZ(),end.getZ())))world.setBlockAndUpdate(pos,state);return new Object[0];}
        @Callback(doc="function(id:string, count:number, damage:number, nbt:string, x:number, y:number, z:number, side:number):boolean - Insert an item stack into the inventory at the specified location. NBT tag is expected in JSON format.") public Object[] insertItem(Context context,Arguments args){ServerLevel world=world(context);ItemStack stack=stack(world,args.checkString(0),args.checkInteger(1),args.checkInteger(2),args.optString(3,""));BlockPos pos=BlockPos.containing(args.checkDouble(4),args.checkDouble(5),args.checkDouble(6));var inventory=InventoryUtils.inventoryAt(world,pos,side(args,7));return inventory.isEmpty()?new Object[]{null,"no inventory"}:new Object[]{InventoryUtils.insertIntoInventory(stack,inventory.get())};}
        @Callback(doc="function(x:number, y:number, z:number, slot:number[, count:number]):number - Reduce the size of an item stack in the inventory at the specified location.") public Object[] removeItem(Context context,Arguments args){ServerLevel world=world(context);BlockPos pos=BlockPos.containing(args.checkDouble(0),args.checkDouble(1),args.checkDouble(2));var inventory=InventoryUtils.anyInventoryAt(world,pos);if(inventory.isEmpty())return new Object[]{null,"no inventory"};int slot=args.checkInteger(3)-1;if(slot<0||slot>=inventory.get().getSlots())throw new IllegalArgumentException("invalid slot");return new Object[]{inventory.get().extractItem(slot,Math.max(0,args.optInteger(4,64)),false).getCount()};}
        @Callback(doc="function(id:string, amount:number, x:number, y:number, z:number, side:number):boolean - Insert some fluid into the tank at the specified location.") public Object[] insertFluid(Context context,Arguments args){ServerLevel world=world(context);ResourceLocation key=ResourceLocation.parse(args.checkString(0));if(!BuiltInRegistries.FLUID.containsKey(key))throw new IllegalArgumentException("invalid fluid id");int amount=args.checkInteger(1);BlockPos position=BlockPos.containing(args.checkDouble(2),args.checkDouble(3),args.checkDouble(4));var handler=world.getCapability(Capabilities.FluidHandler.BLOCK,position,side(args,5));return handler==null?new Object[]{null,"no tank"}:new Object[]{handler.fill(new FluidStack(BuiltInRegistries.FLUID.get(key),Math.max(0,amount)),IFluidHandler.FluidAction.EXECUTE)};}
        @Callback(doc="function(amount:number, x:number, y:number, z:number, side:number):boolean - Remove some fluid from a tank at the specified location.") public Object[] removeFluid(Context context,Arguments args){ServerLevel world=world(context);int amount=args.checkInteger(0);BlockPos position=BlockPos.containing(args.checkDouble(1),args.checkDouble(2),args.checkDouble(3));var handler=world.getCapability(Capabilities.FluidHandler.BLOCK,position,side(args,4));return handler==null?new Object[]{null,"no tank"}:new Object[]{handler.drain(Math.max(0,amount),IFluidHandler.FluidAction.EXECUTE)};}
        @Override public void load(CompoundTag tag){super.load(tag);dimension=tag.contains("dimensionKey")?tag.getString("dimensionKey"):null;dimensionId=tag.getInt("dimension");}
        @Override public void save(CompoundTag tag){super.save(tag);if(dimension!=null)tag.putString("dimensionKey",dimension);tag.putInt("dimension",dimensionId);}
    }
    public static final class TestValue extends AbstractValue {
        private String value="hello";public TestValue(){}
        @Override public Object apply(Context context,Arguments args){OpenComputers.LOGGER.info("TestValue.apply");return value;}
        @Override public void unapply(Context context,Arguments args){OpenComputers.LOGGER.info("TestValue.unapply");value=args.checkString(1);}
        @Override public Object[] call(Context context,Arguments args){OpenComputers.LOGGER.info("TestValue.call");Object[] result=new Object[args.count()];for(int i=0;i<result.length;i++)result[i]=args.checkAny(i);return result;}
        @Override public void dispose(Context context){OpenComputers.LOGGER.info("TestValue.dispose");}
        @Override public void load(CompoundTag tag){value=tag.getString("value");}
        @Override public void save(CompoundTag tag){tag.putString("value",value);}
    }
}
